toolArgs.file_text:
/* ── Chat layout ── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* ── Left sidebar ── */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d23;
    color: #c9d1d9;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #30363d;
    overflow-y: auto;
}

.sidebar-title {
    padding: 16px 16px 8px;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8b949e;
    margin: 0;
}

.channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.channel-item {
    padding: 10px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: #21262d;
}

.channel-item.active {
    background: #21262d;
    border-left-color: #58a6ff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #e6edf3;
}

.channel-desc {
    font-size: 0.78rem;
    color: #8b949e;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #da3633;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ── Main message area ── */
.chat-main {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #0d1117;
    color: #c9d1d9;
    transition: width 0.2s ease;
}

.chat-main.full-width {
    width: 80%;
}

.channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #21262d;
    flex-shrink: 0;
}

.channel-header h2 {
    margin: 0;
    font-size: 1.15rem;
    color: #e6edf3;
}

.channel-header p {
    margin: 4px 0 0;
    font-size: 0.82rem;
    color: #8b949e;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #484f58;
    font-size: 1.1rem;
}

/* ── Message list ── */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 10px;
    color: #8b949e;
    font-size: 0.85rem;
}

.message-row {
    margin-bottom: 6px;
}

.message-bubble {
    padding: 8px 12px;
    border-radius: 6px;
    transition: background 0.15s;
    position: relative;
}

.message-bubble:hover {
    background: #161b22;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #e6edf3;
}

.message-time {
    font-size: 0.75rem;
    color: #484f58;
}

.message-content {
    font-size: 0.92rem;
    line-height: 1.45;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ── Reactions ── */
.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    background: #21262d;
    border: 1px solid #30363d;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: default;
    user-select: none;
}

/* ── Thread link ── */
.thread-link {
