.message-actions {
    display: none;
    position: absolute;
    top: 4px;
    right: 8px;
    gap: 4px;
    background: #161b22;
    border: 1px solid #30363d;
    border-radius: 6px;
    padding: 2px 4px;
}

.message-bubble:hover .message-actions {
    display: flex;
}

.action-btn {
    background: none;
    border: none;
    color: #8b949e;
    font-size: 0.78rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background: #30363d;
    color: #e6edf3;
}

