+/* ── Thread panel ── */
+.chat-thread-panel {
+    width: 25%;
+    min-width: 260px;
+    background: #0d1117;
+    border-left: 1px solid #21262d;
+    display: flex;
+    flex-direction: column;
+    color: #c9d1d9;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #21262d;
+    flex-shrink: 0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #e6edf3;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #8b949e;
+    font-size: 1.1rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #21262d;
+    color: #e6edf3;
+}
+
+.thread-root-quote {
+    padding: 12px 16px;
+    background: #161b22;
+    border-bottom: 1px solid #21262d;
+    font-size: 0.88rem;
+    flex-shrink: 0;
+}
+
+.thread-root-quote p {
+    margin: 6px 0 0;
+    color: #8b949e;
+    white-space: pre-wrap;
+    word-break: break-word;
+}
+
+.thread-messages {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+/* Scrollbar styling */
+.message-list::-webkit-scrollbar,
+.thread-messages::-webkit-scrollbar,
+.chat-sidebar::-webkit-scrollbar {
+    width: 6px;
+}
+
+.message-list::-webkit-scrollbar-thumb,
+.thread-messages::-webkit-scrollbar-thumb,
+.chat-sidebar::-webkit-scrollbar-thumb {
+    background: #30363d;
+    border-radius: 3px;
+}
+
+.message-list::-webkit-scrollbar-track,
+.thread-messages::-webkit-scrollbar-track,
+.chat-sidebar::-webkit-scrollbar-track {
+    background: transparent;
+}
+

